programs._raw:
{
  "name": "Minnesota Supplemental Aid (MSA)",
  "eligibility": {
    "age": 18,
    "income_limits": {
      "summary": "You must be age 18 or older and either receive SSI or be eligible for SSI except that your income is too high. For non-SSI applicants, Minnesota cites MSA income standards that are much lower than federal SSI levels and vary by living arrangement.",
      "table": [
        {
          "living_arrangement": "Lives alone",
          "monthly_standard": "$1,055",
          "source_note": "Cited in Minnesota DHS updates for 2026."
        },
        {
          "living_arrangement": "Lives with others",
          "monthly_standard": "$755",
          "source_note": "Cited in Minnesota DHS updates for 2026."
        },
        {
          "living_arrangement": "Married couple living together, not residing with others",
          "monthly_standard": "$778",
          "source_note": "Minnesota statute lists a state standard of assistance; this is not the same as the income limit but is part of the need standard structure."
        },
        {
          "living_arrangement": "Individual not residing with others",
          "monthly_standard": "$519",
          "source_note": "Minnesota statute lists a state standard of assistance; this is not the same as the income limit but is part of the need standard structure."
        }
      ],
      "important_note": "For non-SSI recipients, DHS materials also describe a gross income limit equal to 300% of the federal SSI federal benefit rate for an individual and 600% for an eligible couple; DB101 summarized that as $2,982/month for an individual and $5,964/month for an eligible couple in 2026. The program also uses a needs/assistance-standard structure that can vary by living arrangement."
    },
    "asset_limits": {
      "summary": "Assets/resources must be within program limits.",
      "limits": {
        "ssi_recipient": "$2,000",
        "non_ssi_recipient": "$10,000"
      },
      "what_counts": [
        "Bank accounts",
        "Other assets",
        "Vehicles",
        "Resources used in eligibility determination for non-SSI applicants"
      ],
      "what_is_exempt_or_not_verified": [
        "For people already receiving SSI, DHS says assets are not re-verified and they are assumed to be within the SSI asset limit."
      ]
    },
    "other_requirements": [
      "Must live in Minnesota.",
      "Must be receiving SSI, or would receive SSI except for excess income.",
      "If not receiving SSI, must be age 65 or older, blind, or disabled under SSI/RSDI criteria.",
      "For non-SSI disability cases, disability is determined by the State Medical Review Team (SMRT).",
      "Must meet MSA assistance-standard/need rules."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Monthly cash assistance. Minnesota DHS says the typical monthly MSA benefit is $81 for an individual and $111 for a couple. For qualifying people with high housing costs, MSA Housing Assistance adds $194 per month to the MSA benefit. MSA Housing Assistance is for people under age 65 whose housing costs are more than 40% of total income.",
    "varies_by": "household_size"
  },
  "application": {
    "methods": [
      "Online: MNbenefits.mn.gov",
      "Paper: Combined Application Form (DHS-5223) submitted to the local county or tribal human services office",
      "Mail: Send the completed paper application to the local county or tribal human services office",
      "In person: Bring the completed paper application to the local county or tribal human services office"
    ],
    "processing_time": "Minnesota law requires the county agency to determine eligibility as soon as required verifications are received and within 30 days after a signed application is received for aged or blind applicants, or within 60 days for applicants with a disability.",
    "waitlist": null,
    "forms": [
      "Combined Application Form (DHS-5223)"
    ],
    "documents": [
      "Identification",
      "SSI award letter, if applicable",
      "Information about who lives in the household and relationships",
      "Citizenship and residency information",
      "Employment information",
      "Bank account statements",
      "Other asset information",
      "Vehicle titles or information",
      "Pay stubs or income verification, if applicable"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide in Minnesota through county or tribal human services agencies.",
    "regional_variations": "Eligibility rules are statewide, but application handling, local office access, and practical processing speed can vary by county or tribal office. There is no program waitlist described in the source materials.",
    "offices_or_providers": [
      "Local county human services office",
      "Local tribal human services office"
    ]
  },
  "official_source": "https://mn.gov/dhs/housing-income/income-assistance/minnesota-supplemental-aid/",
  "gotchas": [
    "MSA is not the same as SSI. Many applicants qualify only because they would receive SSI if their income were not too high.",
    "People already on SSI are usually presumed to meet the asset test, but non-SSI applicants face the $10,000 resource limit.",
    "MSA Housing Assistance is separate from the basic MSA cash benefit and applies only when housing costs exceed 40% of income and the person is under 65.",
    "The application goes through county or tribal human services, not a single statewide office.",
    "The disability pathway for non-SSI applicants may require SMRT review.",
    "Different household/living arrangements affect the assistance standard and can change the practical benefit amount."
  ],
  "data_shape_notes": "This program is a statewide cash benefit with eligibility built around SSI status, age/disability/blindness, income and asset tests, and living-arrangement-based assistance standards. It also has a separate housing-assistance add-on with its own age and housing-cost threshold."
}
